20	/**
21	 * Provide effect for line
22	 */
23	
24	import * as graphic from '../../util/graphic';
25	import Line from './Line';
26	import * as zrUtil from 'zrender/src/core/util';
27	import {createSymbol} from '../../util/symbol';
28	import * as vec2 from 'zrender/src/core/vector';
29	import * as curveUtil from 'zrender/src/core/curve';
30	import type SeriesData from '../../data/SeriesData';
31	import { LineDrawSeriesScope, LineDrawModelOption } from './LineDraw';
32	import Model from '../../model/Model';
33	import { ColorString } from '../../util/types';
34	
35	export type ECSymbolOnEffectLine = ReturnType<typeof createSymbol> & {
36	    __t: number
37	    __lastT: number
38	    __p1: number[]
39	    __p2: number[]
40	    __cp1: number[]
41	};
42	class EffectLine extends graphic.Group {
43	
44	    private _symbolType: string;
45	
46	    private _period: number;
47	
48	    private _loop: boolean;
49	
50	    private _roundTrip: boolean;
51	
52	    private _symbolScale: number[];
53	
54	    constructor(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
55	        super();
56	        this.add(this.createLine(lineData, idx, seriesScope));
57	
58	        this._updateEffectSymbol(lineData, idx);
59	    }
60	
61	    createLine(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope): graphic.Group {
62	        return new Line(lineData, idx, seriesScope);
63	    }
64	
65	    private _updateEffectSymbol(lineData: SeriesData, idx: number) {
66	        const itemModel = lineData.getItemModel<LineDrawModelOption>(idx);
67	        const effectModel = itemModel.getModel('effect');
68	        let size = effectModel.get('symbolSize');
69	        const symbolType = effectModel.get('symbol');
70	        if (!zrUtil.isArray(size)) {
71	            size = [size, size];
72	        }
73	
74	        const lineStyle = lineData.getItemVisual(idx, 'style');
75	        const color = effectModel.get('color') || (lineStyle && lineStyle.stroke);
76	        let symbol = this.childAt(1) as ECSymbolOnEffectLine;
77	
78	        if (this._symbolType !== symbolType) {
79	            // Remove previous
80	            this.remove(symbol);
81	
82	            symbol = createSymbol(
83	                symbolType, -0.5, -0.5, 1, 1, color
84	            ) as ECSymbolOnEffectLine;
85	            symbol.z2 = 100;
86	            symbol.culling = true;
87	
88	            this.add(symbol);
89	        }
90	
91	        // Symbol may be removed if loop is false
92	        if (!symbol) {
93	            return;
94	        }
95	
96	        // Shadow color is same with color in default
97	        symbol.setStyle('shadowColor', color as ColorString);
98	        symbol.setStyle(effectModel.getItemStyle(['color']));
99	
100	        symbol.scaleX = size[0];
101	        symbol.scaleY = size[1];
102	
103	        symbol.setColor(color);
104	
105	        this._symbolType = symbolType;
106	        this._symbolScale = size;
107	
108	        this._updateEffectAnimation(lineData, effectModel, idx);
109	    }
110	
111	    private _updateEffectAnimation(
112	        lineData: SeriesData,
113	        effectModel: Model<LineDrawModelOption['effect']>,
114	        idx: number
115	    ) {
116	
117	        const symbol = this.childAt(1) as ECSymbolOnEffectLine;
118	        if (!symbol) {
119	            return;
120	        }
121	
122	        const points = lineData.getItemLayout(idx);
123	
124	        let period = effectModel.get('period') * 1000;
125	        const loop = effectModel.get('loop');
126	        const roundTrip = effectModel.get('roundTrip');
127	        const constantSpeed = effectModel.get('constantSpeed');
128	        const delayExpr = zrUtil.retrieve(effectModel.get('delay'), function (idx) {
129	            return idx / lineData.count() * period / 3;
130	        });
131	
132	        // Ignore when updating
133	        symbol.ignore = true;
134	
135	        this._updateAnimationPoints(symbol, points);
136	
137	        if (constantSpeed > 0) {
138	            period = this._getLineLength(symbol) / constantSpeed * 1000;
139	        }
140	
141	        if (period !== this._period || loop !== this._loop || roundTrip !== this._roundTrip) {
142	            symbol.stopAnimation();
143	            let delayNum: number;
144	            if (zrUtil.isFunction(delayExpr)) {
145	                delayNum = delayExpr(idx);
146	            }
147	            else {
148	                delayNum = delayExpr;
149	            }
150	            if (symbol.__t > 0) {
151	                delayNum = -period * symbol.__t;
152	            }
153	
154	            this._animateSymbol(
155	                symbol, period, delayNum, loop, roundTrip
156	            );
157	        }
158	
159	        this._period = period;
160	        this._loop = loop;
161	        this._roundTrip = roundTrip;
162	    }
163	
164	    private _animateSymbol(
165	        symbol: ECSymbolOnEffectLine, period: number, delayNum: number, loop: boolean, roundTrip: boolean) {
166	        if (period > 0) {
167	            symbol.__t = 0;
168	            const self = this;
169	            const animator = symbol.animate('', loop)
170	                .when(roundTrip ? period * 2 : period, {
171	                    __t: roundTrip ? 2 : 1
172	                })
173	                .delay(delayNum)
174	                .during(function () {
175	                    self._updateSymbolPosition(symbol);
176	                });
177	            if (!loop) {
178	                animator.done(function () {
179	                    self.remove(symbol);
180	                });
181	            }
182	            animator.start();
183	        }
184	    }
185	
186	    protected _getLineLength(symbol: ECSymbolOnEffectLine) {
187	        // Not so accurate
188	        return (vec2.dist(symbol.__p1, symbol.__cp1)
189	            + vec2.dist(symbol.__cp1, symbol.__p2));
190	    }
191	
192	    protected _updateAnimationPoints(symbol: ECSymbolOnEffectLine, points: number[][]) {
193	        symbol.__p1 = points[0];
194	        symbol.__p2 = points[1];
195	        symbol.__cp1 = points[2] || [
196	            (points[0][0] + points[1][0]) / 2,
197	            (points[0][1] + points[1][1]) / 2
198	        ];
199	    }
200	
201	    updateData(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
202	        (this.childAt(0) as Line).updateData(lineData, idx, seriesScope);
203	        this._updateEffectSymbol(lineData, idx);
204	    }
205	
206	    protected _updateSymbolPosition(symbol: ECSymbolOnEffectLine) {
207	        const p1 = symbol.__p1;
208	        const p2 = symbol.__p2;
209	        const cp1 = symbol.__cp1;
210	        const t = symbol.__t < 1 ? symbol.__t : 2 - symbol.__t;
211	        const pos = [symbol.x, symbol.y];
212	        const lastPos = pos.slice();
213	        const quadraticAt = curveUtil.quadraticAt;
214	        const quadraticDerivativeAt = curveUtil.quadraticDerivativeAt;
215	        pos[0] = quadraticAt(p1[0], cp1[0], p2[0], t);
216	        pos[1] = quadraticAt(p1[1], cp1[1], p2[1], t);
217	
218	        // Tangent
219	        const tx = symbol.__t < 1 ? quadraticDerivativeAt(p1[0], cp1[0], p2[0], t)
220	                 : quadraticDerivativeAt(p2[0], cp1[0], p1[0], 1 - t);
221	         const ty = symbol.__t < 1 ? quadraticDerivativeAt(p1[1], cp1[1], p2[1], t)
222	                 : quadraticDerivativeAt(p2[1], cp1[1], p1[1], 1 - t);
223	
224	
225	        symbol.rotation = -Math.atan2(ty, tx) - Math.PI / 2;
226	        // enable continuity trail for 'line', 'rect', 'roundRect' symbolType
227	        if (this._symbolType === 'line' || this._symbolType === 'rect' || this._symbolType === 'roundRect') {
228	            if (symbol.__lastT !== undefined && symbol.__lastT < symbol.__t) {
229	                symbol.scaleY = vec2.dist(lastPos, pos) * 1.05;
230	                // make sure the last segment render within endPoint
231	                if (t === 1) {
232	                    pos[0] = lastPos[0] + (pos[0] - lastPos[0]) / 2;
233	                    pos[1] = lastPos[1] + (pos[1] - lastPos[1]) / 2;
234	                }
235	            }
236	            else if (symbol.__lastT === 1) {
237	                // After first loop, symbol.__t does NOT start with 0, so connect p1 to pos directly.
238	                symbol.scaleY = 2 * vec2.dist(p1, pos);
239	            }
240	            else {
241	                symbol.scaleY = this._symbolScale[1];
242	            }
243	        }
244	        symbol.__lastT = symbol.__t;
245	        symbol.ignore = false;
246	        symbol.x = pos[0];
247	        symbol.y = pos[1];
248	    }
249	
250	
251	    updateLayout(lineData: SeriesData, idx: number) {
252	        (this.childAt(0) as Line).updateLayout(lineData, idx);
253	
254	        const effectModel = lineData.getItemModel<LineDrawModelOption>(idx).getModel('effect');
255	        this._updateEffectAnimation(lineData, effectModel, idx);
256	    }
257	}
258	export default EffectLine;
