20	import Polyline from './Polyline';
21	import EffectLine, {ECSymbolOnEffectLine} from './EffectLine';
22	import * as vec2 from 'zrender/src/core/vector';
23	import { LineDrawSeriesScope } from './LineDraw';
24	import SeriesData from '../../data/SeriesData';
25	
26	
27	class EffectPolyline extends EffectLine {
28	    private _lastFrame = 0;
29	    private _lastFramePercent = 0;
30	    private _length: number;
31	
32	    private _points: number[][];
33	    private _offsets: number[];
34	
35	    // Override
36	    createLine(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
37	        return new Polyline(lineData, idx, seriesScope);
38	    };
39	
40	    // Override
41	    protected _updateAnimationPoints(symbol: ECSymbolOnEffectLine, points: number[][]) {
42	        this._points = points;
43	        const accLenArr = [0];
44	        let len = 0;
45	        for (let i = 1; i < points.length; i++) {
46	            const p1 = points[i - 1];
47	            const p2 = points[i];
48	            len += vec2.dist(p1, p2);
49	            accLenArr.push(len);
50	        }
51	        if (len === 0) {
52	            this._length = 0;
53	            return;
54	        }
55	
56	        for (let i = 0; i < accLenArr.length; i++) {
57	            accLenArr[i] /= len;
58	        }
59	        this._offsets = accLenArr;
60	        this._length = len;
61	    };
62	
63	    // Override
64	    protected _getLineLength() {
65	        return this._length;
66	    };
67	
68	    // Override
69	    protected _updateSymbolPosition(symbol: ECSymbolOnEffectLine) {
70	        const t = symbol.__t < 1 ? symbol.__t : 2 - symbol.__t;
71	        const points = this._points;
72	        const offsets = this._offsets;
73	        const len = points.length;
74	
75	        if (!offsets) {
76	            // Has length 0
77	            return;
78	        }
79	
80	        const lastFrame = this._lastFrame;
81	        let frame: number;
82	
83	        if (t < this._lastFramePercent) {
84	            // Start from the next frame
85	            // PENDING start from lastFrame ?
86	            const start = Math.min(lastFrame + 1, len - 1);
87	            for (frame = start; frame >= 0; frame--) {
88	                if (offsets[frame] <= t) {
89	                    break;
90	                }
91	            }
92	            // PENDING really need to do this ?
93	            frame = Math.min(frame, len - 2);
94	        }
95	        else {
96	            for (frame = lastFrame; frame < len; frame++) {
97	                if (offsets[frame] > t) {
98	                    break;
99	                }
100	            }
101	            frame = Math.min(frame - 1, len - 2);
102	        }
103	
104	        const p = (t - offsets[frame]) / (offsets[frame + 1] - offsets[frame]);
105	        const p0 = points[frame];
106	        const p1 = points[frame + 1];
107	        symbol.x = p0[0] * (1 - p) + p * p1[0];
108	        symbol.y = p0[1] * (1 - p) + p * p1[1];
109	
110	        const tx = symbol.__t < 1 ? p1[0] - p0[0] : p0[0] - p1[0];
111	        const ty = symbol.__t < 1 ? p1[1] - p0[1] : p0[1] - p1[1];
112	        symbol.rotation = -Math.atan2(ty, tx) - Math.PI / 2;
113	
114	        this._lastFrame = frame;
115	        this._lastFramePercent = t;
116	
117	        symbol.ignore = false;
118	    };
119	
120	}
121	
122	export default EffectPolyline;
